Set-Location (Join-Path $PSScriptRoot "..")  # c: run from pytorch_implementations
# n: generated by size_match.py, all models with about the same number of parameters
$py = "..\.venv\Scripts\python"

& $py train.py --data shakespeare.txt --model slstm --hidden 320
& $py train.py --data shakespeare.txt --model mlstm --hidden 356 --mlstm_variant base
& $py train.py --data dyck_train.txt --model mlstm --hidden 356 --mlstm_variant base
& $py train.py --data shakespeare.txt --model mlstm --hidden 320 --mlstm_variant separate
& $py train.py --data dyck_train.txt --model mlstm --hidden 320 --mlstm_variant separate
& $py train.py --data shakespeare.txt --model xlstm --hidden 128 --blocks s,m
& $py train.py --data dyck_train.txt --model lstm
& $py train.py --data dyck_train.txt --model slstm --hidden 320
